// Generates src/currencies.mjs from data/currencies.json. Run as: node scripts/gen.mjs
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const rows = JSON.parse(fs.readFileSync(path.join(root, "data", "currencies.json"), "utf8"));
const body = rows.map((r) => "  " + r.code + ": " + r.digits + ",").join("\n");
const out =
  "// GENERATED by scripts/gen.mjs from data/currencies.json - do not edit by hand.\n" +
  "const DIGITS = {\n" + body + "\n};\n\n" +
  "export function digitsFor(code) {\n" +
  "  if (!(code in DIGITS)) throw new RangeError(\"unknown currency \" + code);\n" +
  "  return DIGITS[code];\n" +
  "}\n";
fs.writeFileSync(path.join(root, "src", "currencies.mjs"), out);
